import unittest
from redact_counts import *
class RedactCounts(unittest.TestCase):
    def test_tuple_and_substitution_count(self):
        for text,count,expected in [('bin12 shelf345 rack6',0,('bin# shelf# rack#',3)),('bin12 shelf345 rack6',1,('bin# shelf345 rack6',1)),('bin12 shelf345 rack6',2,('bin# shelf# rack6',2)),('oak',0,('oak',0)),('',0,('',0)),('12',9,('#',1)),('箱１２-٣4',0,('箱#-#',2))]:
            with self.subTest(text=text,count=count):
                self.assertEqual(mask_numbers(text,count),expected)

if __name__ == '__main__':
    unittest.main()

